import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position, rotation, and scale from config
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ = [0, 0, 0], scaleXYZ = [1, 1, 1] } = config.scenePosition;

    group.position.set(x, y, z);

    group.rotation.order = 'XYZ';
    group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);

    group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
  }

  // Create plane geometry (1x1)
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture from imageUrl (cached by ctx.textureLoader)
  const textureMap = ctx.textureLoader.load(config.imageUrl);

  // Create TSL-based material with texture
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(textureMap);

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Initialize event handlers (empty for this static card)
  group.userData.handlers = {};

  // Cleanup function to dispose resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  return group;
}
